config.script:
	import system
	import csv
	import re
	from org.apache.poi.xssf.usermodel import XSSFWorkbook
	from org.apache.poi.ss.usermodel import DataFormatter, CellType
	from java.io import FileInputStream

	# === Constants ===
#	output_csv_path = "C:/Reports/ip_analysis_report.csv"
	selectedServer = self.getSibling("Server Select").props.value

	# === Get uploaded Excel file path from the view ===
	excel_file_path = self.view.custom.uploadedExcelPath
	if not excel_file_path or not system.file.fileExists(excel_file_path):
		system.util.getLogger("IP_Checker").warn("Excel file not found: " + str(excel_file_path))
		return

	# === IP cleaning and sorting helpers ===
	def clean_ip(ip_address):
		if ip_address:
			ip_address = re.sub(r"[^\d\.]", "", str(ip_address))
			match = re.search(r"\b(?:\d{1,3}\.){3}\d{1,3}\b", ip_address)
			if match:
				return match.group(0)
		return None

	def ip_sort_key(ip):
		return tuple(map(int, ip.split("."))) if ip else (0, 0, 0, 0)

	def normalize_ip_set(ip_set):
		return set(clean_ip(ip) for ip in ip_set if clean_ip(ip))

	# === Get IPs from Gateway Devices using RCGetDevices and ignoring BACnetIP ===
	def get_device_ips_from_gateway(selectedServer):
		device_ips = set()
		ip_count = {}

		if selectedServer not in ["", None]:
			ioData = system.tag.readBlocking(["[default]IO_Server_List"])[0].value

			for row in range(ioData.rowCount):
				if ioData.getValueAt(row, "Name") == selectedServer:
					server = ioData.getValueAt(row, "Server")
					projectName = ioData.getValueAt(row, "ProjectName")

					if server in ["", None]:
						if projectName in ["", None]:
							data = system.util.sendRequest(system.util.getProjectName(), "RCGetDevices", scope="G")
						else:
							data = system.util.sendRequest(projectName, "RCGetDevices", scope="G")
					else:
						data = system.util.sendRequest(projectName, "RCGetDevices", scope="G", remoteServer=server)

					# Filter non-BACnetIP hostnames
					non_bacnet_hostnames = [
						clean_ip(item.get("Hostname", ""))
						for item in data if item.get("Driver") != "BACnetIP"
					]

					for ip in non_bacnet_hostnames:
						if ip:
							device_ips.add(ip)
							ip_count[ip] = ip_count.get(ip, 0) + 1

		conflicting_gateway_ips = {ip for ip, count in ip_count.items() if count > 1}
		return device_ips, conflicting_gateway_ips

	# === Get IPs from Excel File ===
	def get_excel_ips(file_path):
		excel_ips = set()
		ip_count = {}
		formatter = DataFormatter()

		try:
			fis = FileInputStream(file_path)
			workbook = XSSFWorkbook(fis)

			for sheet_index in range(workbook.getNumberOfSheets()):
				sheet = workbook.getSheetAt(sheet_index)

				# Track IP Address columns
				ip_columns = []

				for row_num in range(sheet.getLastRowNum() + 1):
					row = sheet.getRow(row_num)
					if row is None:
						continue

					# First pass: identify all IP Address columns
					if row_num <= 20:  # Scan header rows
						for col_index in range(row.getLastCellNum()):
							cell = row.getCell(col_index)
							if cell is None:
								continue
							label = formatter.formatCellValue(cell).strip().lower()
							if label.startswith("ip address"):
								ip_columns.append(col_index)
						continue  # Skip to next row after header scan

					# Second pass: extract from all known IP Address columns
					for col_index in ip_columns:
						cell = row.getCell(col_index)
						if cell is None:
							continue

						ip_text = formatter.formatCellValue(cell).strip()

						if not clean_ip(ip_text):
							try:
								if cell.getCellType() == CellType.NUMERIC:
									ip_text = str(cell.getNumericCellValue())
								else:
									ip_text = cell.toString()
							except:
								pass

						ip = clean_ip(ip_text)
						if ip:
							excel_ips.add(ip)
							ip_count[ip] = ip_count.get(ip, 0) + 1

			fis.close()
			conflicting_excel_ips = {ip for ip, count in ip_count.items() if count > 1}
			return excel_ips, conflicting_excel_ips

		except Exception as e:
			system.util.getLogger("IP_Checker").error("Error reading Excel file: " + str(e))
			return set(), set()

	# === Generate report ===
	def generate_output():
		ignition_ips, conflict_gateway = get_device_ips_from_gateway(selectedServer)
		excel_ips, conflict_excel = get_excel_ips(excel_file_path)

		norm_gateway = normalize_ip_set(ignition_ips)
		norm_excel = normalize_ip_set(excel_ips)
		norm_conflict_gateway = normalize_ip_set(conflict_gateway)
		norm_conflict_excel = normalize_ip_set(conflict_excel)

		extra_in_gateway = sorted(norm_gateway - norm_excel, key=ip_sort_key)
#		matching_ips = sorted(norm_gateway & norm_excel, key=ip_sort_key)
		conflicting_gateway_ips = sorted(norm_conflict_gateway, key=ip_sort_key)
		conflicting_excel_ips = sorted(norm_conflict_excel, key=ip_sort_key)

		system.util.getLogger("IP_Debug").info("Gateway IPs: " + str(sorted(norm_gateway)))
		system.util.getLogger("IP_Debug").info("Excel IPs: " + str(sorted(norm_excel)))
		system.util.getLogger("IP_Debug").info("Extra in Gateway: " + str(extra_in_gateway))

		headers = ["Status", "IP Address"]
		data = []

		try:
			filter_selection = self.view.custom.ipFilter
		except AttributeError:
			filter_selection = "all"

		if filter_selection == "gateway":
			for ip in conflicting_gateway_ips:
				data.append(["Conflict in Gateway", ip])
		elif filter_selection == "excel":
			for ip in conflicting_excel_ips:
				data.append(["Conflict in Excel", ip])
		elif filter_selection == "extra":
			for ip in extra_in_gateway:
				data.append(["Extra in Gateway", ip])
		elif filter_selection == "all":
			for ip in conflicting_gateway_ips:
				data.append(["Conflict in Gateway", ip])
			for ip in conflicting_excel_ips:
				data.append(["Conflict in Excel", ip])
			for ip in extra_in_gateway:
				data.append(["Extra in Gateway", ip])
#			for ip in matching_ips:
#				data.append(["Matching", ip])
		else:
			system.util.getLogger("IP_Checker").warn("Unknown filter: " + str(filter_selection))

		# Output CSV
#		try:
#			with open(output_csv_path, 'w') as file:
#				writer = csv.writer(file)
#				writer.writerow(headers)
#				writer.writerows(data)
#			system.util.getLogger("IP_Checker").info("Report saved to " + output_csv_path)
#		except Exception as e:
#			system.util.getLogger("IP_Checker").error("Error writing CSV file: " + str(e))

		return system.dataset.toDataSet(headers, data)

	# === Execute and bind to table ===
	table_dataset = generate_output()


	self.parent.parent.getChild("Table").getChild("Results").getChild("FlexContainer_Table").getChild("Table_IP").props.data = system.dataset.toPyDataSet(table_dataset)
